# KNIRV Wizened Environment Containerfile
# Implements the WizenedEnvironmentGuide approach for Podman deployment
# Compatible with both Podman and Docker runtimes

FROM ubuntu:22.04

# Install system dependencies
RUN apt-get update && apt-get install -y \
    curl \
    wget \
    ca-certificates \
    python3 \
    python3-pip \
    bash \
    && rm -rf /var/lib/apt/lists/*

# Set working directory
WORKDIR /app

# Copy pre-built artifacts (built locally with build-local-release.sh)
COPY bin/ ./bin/
COPY config/ ./config/
COPY assets/ ./assets/
COPY developer-portal/ ./developer-portal/
COPY graphchain-explorer/ ./graphchain-explorer/
COPY index.html ./
COPY package*.json ./

# Install Node.js (for npm operations on host)
ENV NODE_VERSION=v18.18.0
RUN curl -L "https://nodejs.org/dist/${NODE_VERSION}/node-${NODE_VERSION}-linux-x64.tar.xz" | tar -xJ \
    && mv node-${NODE_VERSION}-linux-x64 /usr/local/node \
    && ln -s /usr/local/node/bin/node /usr/local/bin/node \
    && ln -s /usr/local/node/bin/npm /usr/local/bin/npm

# Install npm dependencies
RUN npm install

# WASM runtime not needed for native orchestrator deployment

# Make all binaries executable
RUN chmod +x ./bin/*

# Create necessary directories
RUN mkdir -p logs data

# Expose the port
EXPOSE 10000

# Health check
HEALTHCHECK --interval=30s --timeout=10s --start-period=5s --retries=3 \
    CMD curl -f http://localhost:10000/health || exit 1

# Start the native KNIRV orchestrator
# VFS toolchain available separately for development tools
CMD ["./bin/knirv-orchestrator"]


