83	// GetDVEWorkers handles GET /api/dve/workers — aggregates DVE nodes + tasks as active workers
84	func (h *DVEHandlers) GetDVEWorkers(w http.ResponseWriter, r *http.Request) {
85		type ActiveWorker struct {
86			ID             string            `json:"id"`
87			Name           string            `json:"name"`
88			Type           string            `json:"type"`
89			Status         string            `json:"status"`
90			LastActivity   string            `json:"lastActivity"`
91			TasksCompleted int               `json:"tasksCompleted"`
92			CPUUsage       float64           `json:"cpuUsage,omitempty"`
93			MemoryUsage    float64           `json:"memoryUsage,omitempty"`
94			Metadata       map[string]string `json:"metadata,omitempty"`
95		}
96	
97		workers := make([]ActiveWorker, 0)
98	
99		if h.dveManager != nil {
100			nodes := h.dveManager.GetAllNodes()
101			for _, node := range nodes {
102				workerStatus := "idle"
103				switch node.Status {
104				case "online", "active":
105					workerStatus = "active"
106				case "offline":
107					workerStatus = "disconnected"
108				case "error":
109					workerStatus = "error"
110				}
111	
112				tasks, _ := h.dveManager.GetNodeTasks(node.ID)
113				completed := 0
114				for _, t := range tasks {
115					if t.Status == "completed" {
116						completed++
117					}
118				}
119	
120				workers = append(workers, ActiveWorker{
121					ID:             node.ID,
122					Name:           node.Name,
123					Type:           "agent",
124					Status:         workerStatus,
125					LastActivity:   node.LastHeartbeat.Format(time.RFC3339),
126					TasksCompleted: completed,
127					CPUUsage:       node.CPUUsage,
128					MemoryUsage:    node.MemoryUsage,
129					Metadata: map[string]string{
130						"tee_type": node.TEEType,
131						"location": node.Location,
132					},
133				})
134			}
135	
136			// Add running tasks as workflow workers
137			allTasks, err := h.dveManager.ListTasks("running", "")
138			if err == nil {
139				for _, task := range allTasks {
140					workers = append(workers, ActiveWorker{
141						ID:           task.ID,
142						Name:         fmt.Sprintf("Task: %s", task.Type),
143						Type:         "workflow",
144						Status:       "active",
145						LastActivity: task.UpdatedAt.Format(time.RFC3339),
146						Metadata: map[string]string{
147							"node_id": task.AssignedNodeID,
148							"type":    task.Type,
149						},
150					})
151				}
152			}
153		}
154	
155		w.Header().Set("Content-Type", "application/json")
156		json.NewEncoder(w).Encode(map[string]interface{}{
157			"workers":   workers,
158			"total":     len(workers),
159			"timestamp": getCurrentTimestamp(),
160		})
161	}
