365	// GetDVENodes handles GET /api/dve-nodes
366	func (h *DVEHandlers) GetDVENodes(w http.ResponseWriter, r *http.Request) {
367		if h.dveManager == nil {
368			// Return empty nodes list instead of error when DVE manager is not initialized
369			w.Header().Set("Content-Type", "application/json")
370			json.NewEncoder(w).Encode(map[string]interface{}{
371				"nodes":     []interface{}{},
372				"total":     0,
373				"timestamp": getCurrentTimestamp(),
374			})
375			return
376		}
377	
378		// Parse query parameters for filtering
379		filter := &dvemanager.NodeFilter{
380			Status:   r.URL.Query().Get("status"),
381			TEEType:  r.URL.Query().Get("tee_type"),
382			Location: r.URL.Query().Get("location"),
383		}
384	
385		// Parse limit parameter
386		limitStr := r.URL.Query().Get("limit")
387		if limitStr != "" {
388			if limit, err := strconv.Atoi(limitStr); err == nil && limit > 0 {
389				filter.Limit = limit
390			}
391		}
392	
393		nodes, err := h.dveManager.GetNodes(filter)
394		if err != nil {
395			// If error is "not found", return empty array instead of 500 error
396			if strings.Contains(err.Error(), "not found") {
397				response := DVENodeResponse{
398					Success:   true,
399					Data:      []interface{}{}, // Empty array
400					Total:     0,
401					Timestamp: getCurrentTimestamp(),
402				}
403				w.Header().Set("Content-Type", "application/json")
404				json.NewEncoder(w).Encode(response)
405				return
406			}
407	
408			// For other errors, still return 500
409			response := DVENodeResponse{
410				Success:   false,
411				Error:     "Failed to fetch DVE nodes: " + err.Error(),
412				Timestamp: getCurrentTimestamp(),
413			}
414			w.Header().Set("Content-Type", "application/json")
415			w.WriteHeader(http.StatusInternalServerError)
416			json.NewEncoder(w).Encode(response)
417			return
418		}
419	
420		// Apply role-based filtering for observer (Developer) role.
421		// When the observer has existing creations, show only their nodes.
422		// When they have no creations yet (new user / demo state), show all nodes
423		// so that demo DVE nodes are visible and the dashboard is not empty.
424		authCtx := middleware.GetAuthContext(r)
425		if authCtx != nil && authCtx.Role == "observer" && h.dveManager != nil {
426			creations, err := h.dveCreationService.GetUserDVECreations(authCtx.UserID)
427			if err != nil || len(creations) == 0 {
428				// No creations yet — fall through to return all nodes (including demo nodes).
429			} else {
430				// User has creations: filter to only their nodes.
431				userNodeMap := make(map[string]bool)
432				for _, creation := range creations {
433					userNodeMap[creation.DVENodeID] = true
434				}
435	
436				filteredNodes := make([]interface{}, 0)
437				for _, node := range nodes {
438					if userNodeMap[node.ID] {
439						filteredNodes = append(filteredNodes, node)
440					}
441				}
442	
443				response := DVENodeResponse{
444					Success:   true,
445					Data:      filteredNodes,
446					Total:     len(filteredNodes),
447					Timestamp: getCurrentTimestamp(),
448				}
449				w.Header().Set("Content-Type", "application/json")
450				json.NewEncoder(w).Encode(response)
451				return
452			}
453		}
454	
455		// For admin, validator roles, and observers with no creations, return all nodes.
456		response := DVENodeResponse{
457			Success:   true,
458			Data:      nodes,
459			Total:     len(nodes),
460			Timestamp: getCurrentTimestamp(),
461		}
462	
463		w.Header().Set("Content-Type", "application/json")
464		json.NewEncoder(w).Encode(response)
465	}
